import {prepareFormMigration} from './form-migration.mjs';
import {prepareLayoutMigration} from './layout-migration.mjs';
import {createGame,command,advance,validate,summarize} from './engine.mjs';
import * as persistence from './storage.mjs';
export class GameSession{
 constructor({storage=persistence,workerFactory=()=>new Worker(new URL('./offline-worker.mjs',import.meta.url),{type:'module'}),now=()=>Date.now(),notify=()=>{}}={}){Object.assign(this,{storage,workerFactory,now,notify});this.state=null;this.revision=0;this.resolvedAt=now();this.stateWallAt=this.resolvedAt;this.phase='loading';this.queue=Promise.resolve();this.importGeneration=0;this.pendingImport=null;this.worker=null;this.workerGeneration=0;this.error=null;this.legacy=[];this.busy=false;this.report=null}
 changed(){this.notify(this)}
 block(error){this.error=error instanceof Error?error:Error(String(error));this.phase='blocked';this.workerGeneration++;this.worker?.terminate();this.worker=null;this.changed()}
 start(){if(this.starting)return this.starting;this.starting=this.startInternal().finally(()=>{this.starting=null});return this.starting}
 async retryOwnership(){if(this.phase!=='readonly')return false;await this.start();return this.session?.owned===true&&this.phase!=='blocked'}
 async startInternal(){try{this.session=await this.storage.acquireSession();this.legacy=await this.storage.preserveLegacy();const env=await this.storage.readSave();if(env){this.state=env.state;this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.stateWallAt=env.resolvedAt}if(!this.session.owned){this.phase='readonly';this.changed();return}if(this.state){if(this.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後重新載入。原始進度仍保留，可匯出備份。');await this.recoverForms();await this.recoverLayout();await this.recoverFusion();await this.catchUp();}else{this.phase='creation';this.changed()}}catch(e){this.block(e)}}
 async recoverForms(){const change=prepareFormMigration(this.state);if(!change)return;await this.save(change.state,this.stateWallAt,{archive:true,operation:'form-collection-upgrade'});this.state=change.state;this.formMigrationNotice=change.notice}
 async recoverLayout(){const change=prepareLayoutMigration(this.state);if(!change)return;await this.save(change.state,this.stateWallAt,{archive:true,operation:'settlement-layout-update'});this.state=change.state;this.layoutNotice=change.notice}
 async recoverFusion(){if(!this.state?.fusion.pending)return;const next=structuredClone(this.state),result=command(next,{type:'fusionCommit',transactionId:next.fusion.pending.id});if(!result.ok)throw Error(result.error);await this.save(next,this.stateWallAt,{operation:'recover-reserved-fusion'});this.state=next}
 save(state=this.state,at=this.stateWallAt,options={}){const snapshot=structuredClone(state);const task=this.queue.then(()=>this.storage.writeSave(snapshot,this.revision,at,options)).then(env=>{this.revision=env.revision;this.resolvedAt=env.resolvedAt;return env});this.queue=task.catch(()=>{});return task}
 async create(classId,name,attrs,seed=this.now()){if(this.busy||['readonly','blocked','catchup','paused','rollback-ready'].includes(this.phase))return;this.busy=true;try{const next=createGame(classId,name,attrs,seed);await this.save(next,this.now(),{archive:!!this.state,operation:'create-adventure'});this.state=next;this.stateWallAt=this.resolvedAt;this.phase='ready';this.report=null;this.changed()}catch(e){this.block(e)}finally{this.busy=false;this.changed()}}
 async act(action){if(this.phase!=='ready'||this.busy||!this.state)return{ok:false,error:'目前無法操作'};this.busy=true;const previous=structuredClone(this.state);try{const result=command(this.state,action);if(!result.ok)return result;await this.save(this.state,this.stateWallAt,{operation:action.type});this.changed();return result}catch(e){this.state=previous;this.block(e);return{ok:false,error:e.message}}finally{this.busy=false;this.changed()}}
 tick(seconds){if(this.phase!=='ready'||this.busy||!this.state)return[];try{const result=advance(this.state,seconds);this.stateWallAt+=seconds*1000;return result.events}catch(e){this.block(e);return[]}}
 async checkpoint(){if(this.phase!=='ready'||this.busy||!this.state)return;try{await this.save()}catch(e){this.block(e)}}
 async catchUp({offline=this.catchupOffline??true}={}){if(this.rollbackRestored)return;if(!this.state||this.busy||!this.session?.owned||this.phase==='catchup')return;this.catchupOffline=offline;this.catchupPauseRequested=false;this.phase='catchup';this.changed();const generation=++this.workerGeneration;try{await this.queue;const env=await this.storage.readSave();if(generation!==this.workerGeneration)return;this.state=env.state;this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.stateWallAt=env.resolvedAt;if(env.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後重新載入。原始進度仍保留，可匯出備份。');const seconds=Math.max(0,(this.now()-env.resolvedAt)/1000);if(seconds<.001){this.phase='ready';this.changed();return}this.catchupOrigin??={before:summarize(this.state),start:env.resolvedAt};const originalBefore=this.catchupOrigin.before,start=env.resolvedAt;let base=start;this.progress={processed:0,total:seconds};await new Promise((resolve,reject)=>{const worker=this.workerFactory();this.worker=worker;let commits=Promise.resolve();worker.onerror=e=>reject(Error(e.message||'離線計算中斷'));worker.onmessage=({data:d})=>{if(generation!==this.workerGeneration)return;if(d.type==='error'){reject(Error(d.message));return}if(!['checkpoint','done','paused'].includes(d.type))return;const v=validate(d.state);if(!v.ok){reject(Error(v.errors.join('；')));return}commits=commits.then(async()=>{if(generation!==this.workerGeneration)return;await this.save(d.state,base+d.processed*1000,{operation:'offline-checkpoint'});this.state=d.state;this.stateWallAt=base+d.processed*1000;this.progress={processed:d.processed,total:d.total};this.changed();if(d.type==='checkpoint'&&d.checkpointId!==undefined)worker.postMessage({type:'ack',checkpointId:d.checkpointId})});commits.catch(reject);if(d.type==='done'||d.type==='paused'){worker.terminate();this.worker=null;commits.then(()=>{if(generation!==this.workerGeneration)return;this.phase=d.type==='paused'?'paused':'ready';if(offline)this.report={before:originalBefore,after:summarize(this.state),seconds:(this.resolvedAt-this.catchupOrigin.start)/1000};resolve()}).catch(reject)}};worker.postMessage({type:'simulate',state:this.state,seconds,offline});if(this.catchupPauseRequested)worker.postMessage({type:'pause'})});if(this.phase==='ready'&&generation===this.workerGeneration){const tail=(this.now()-this.resolvedAt)/1000;if(tail>.25){await this.catchUp({offline});return}if(tail>0){const at=this.now();advance(this.state,(at-this.stateWallAt)/1000,{offline});this.stateWallAt=at;await this.save(this.state,at,{operation:'offline-tail'})}}if(this.phase==='ready'){if(offline)this.report={before:this.catchupOrigin.before,after:summarize(this.state),seconds:(this.stateWallAt-this.catchupOrigin.start)/1000};this.catchupOrigin=null}this.changed()}catch(e){this.block(e)}}
 pauseCatchUp(){if(this.phase==='catchup'){this.catchupPauseRequested=true;this.worker?.postMessage({type:'pause'})}}
 cancelImport(){this.importGeneration++;this.pendingImport=null;this.changed()}
 async selectImport(file){const generation=++this.importGeneration;this.pendingImport=null;if(!file)return;if(file.size>20*1024*1024)throw Error('備份過大');const raw=await file.text();if(generation!==this.importGeneration)return;const parsed=await this.storage.parseImport(raw);if(generation!==this.importGeneration)return;this.pendingImport=parsed;this.changed()}
 async restoreBeforeUpgrade(){if(!this.pendingImport?.state||this.busy||!this.session?.owned||!['ready','creation'].includes(this.phase))return false;const imported=structuredClone(this.pendingImport.state);if(imported.formProgress!==undefined||!validate(imported).ok||JSON.stringify(imported).includes('ITEM-FORM-CONTRACT-'))return false;this.busy=true;try{await this.save(imported,this.now(),{archive:!!this.state,operation:'restore-before-upgrade-no-simulation'});this.state=imported;this.stateWallAt=this.resolvedAt;this.pendingImport=null;this.importGeneration++;this.report=null;this.rollbackRestored=true;this.phase='rollback-ready';return true}catch(e){this.block(e);return false}finally{this.busy=false;this.changed()}}
 async confirmImport(){if(!this.pendingImport?.state||this.busy||!['ready','creation'].includes(this.phase))return false;this.busy=true;const imported=structuredClone(this.pendingImport.state),at=Math.min(this.now(),this.pendingImport.resolvedAt??this.now());this.cancelImport();let accepted=false;try{await this.save(imported,at,{archive:!!this.state,operation:'confirmed-import'});this.state=imported;this.stateWallAt=this.resolvedAt;await this.recoverForms();await this.recoverLayout();await this.recoverFusion();this.phase='ready';this.report=null;accepted=true;this.changed()}catch(e){this.block(e)}finally{this.busy=false;this.changed()}if(accepted){await this.catchUp({offline:true});return this.phase!=='blocked'}return false}
 async export(){if(!this.state)return null;return this.storage.exportEnvelope(structuredClone(this.state),this.stateWallAt)}
}
